import { cookies, headers } from 'next/headers'

// Pull the highest-priority language tag out of an Accept-Language header.
// e.g. "en-US,en;q=0.9,fr;q=0.8" -> "en-US"
function preferredLanguage(acceptLanguage: string | null) {
  if (!acceptLanguage) return 'unknown'
  const [first] = acceptLanguage.split(',')
  return first?.split(';')[0]?.trim() || 'unknown'
}

export default async function UserPreferences() {
  const cookieStore = await cookies()
  const headersList = await headers()

  const theme = cookieStore.get('theme')?.value ?? 'light'
  const language = preferredLanguage(headersList.get('accept-language'))

  return (
    <section>
      <p>Current theme: {theme}</p>
      <p>Preferred language: {language}</p>
    </section>
  )
}

